export interface GitHubConfig {
  /** Stable, non-secret stream prefix for this installation. */
  sourceId: string
  /** Each repository creates independent issues and stargazers streams. */
  repositories: readonly string[]
  start: Date
  overlapMs: number
  pageSize: number
}

// Set source selection here; raw destinations are declared in sources/.
export const githubConfig: GitHubConfig = {
  sourceId: 'github',
  repositories: ['obsessiondb/chkit'],
  start: new Date('2008-01-01T00:00:00Z'),
  overlapMs: 5 * 60 * 1000,
  pageSize: 100,
}

import { HttpError, IngestConfigError, paginate, type ErrorClassifier, type FetchContext } from '@chkit/plugin-ingest'

import type { GitHubConfig } from './config.js'

export interface GitHubClientDeps {
  fetch: (url: string, init: RequestInit) => Promise<Response>
  token: () => string | undefined
}

export const defaultGitHubClientDeps: GitHubClientDeps = {
  fetch: (url, init) => fetch(url, init),
  token: () => process.env.GITHUB_TOKEN,
}

export function readGitHubPages<T>(
  context: FetchContext,
  input: { path: string; accept?: string; params?: Record<string, string> },
  config: GitHubConfig,
  deps: GitHubClientDeps,
) {
  const first = new URL(`https://api.github.com${input.path}`)
  for (const [key, value] of Object.entries({ ...input.params, per_page: String(config.pageSize) })) first.searchParams.set(key, value)
  return paginate<T, string>({
    context, initial: first.toString(), label: `GET ${input.path}`,
    fetchPage: async (cursor = first.toString(), signal) => {
      const response = await requestGitHub(cursor, input.accept, signal, deps)
      const items: unknown = await response.json()
      if (!Array.isArray(items)) throw new IngestConfigError(`GitHub ${input.path} response is not an array.`)
      const next = nextLink(response.headers.get('link'), cursor)
      if (next === cursor) throw new IngestConfigError('GitHub repeated a page URL.')
      return { items: items as T[], next }
    },
  })
}

export async function requestGitHub(url: string, accept = 'application/vnd.github+json', signal: AbortSignal, deps: GitHubClientDeps): Promise<Response> {
  const token = deps.token()?.trim()
  if (!token) throw new IngestConfigError('Set GITHUB_TOKEN.')
  const response = await deps.fetch(url, { signal: AbortSignal.any([signal, AbortSignal.timeout(30_000)]), redirect: 'error',
    headers: { Authorization: `Bearer ${token}`, Accept: accept, 'X-GitHub-Api-Version': '2022-11-28' } })
  if (!response.ok) throw await HttpError.fromResponse(response)
  return response
}

/** A 403 can mean rate exhaustion; ordinary permission failures remain permanent. */
export function classifyGitHubError(cause: unknown): ReturnType<ErrorClassifier> {
  if (!(cause instanceof HttpError) || (cause.status !== 403 && cause.status !== 429)) return undefined
  const headers = cause.response.headers
  if (headers.get('x-ratelimit-remaining') !== '0' && !headers.has('retry-after')) return undefined
  const resetSeconds = Number(headers.get('x-ratelimit-reset'))
  const untilReset = Number.isFinite(resetSeconds) && resetSeconds > 0 ? Math.max(0, resetSeconds * 1000 - Date.now()) : undefined
  return { kind: 'rate_limited', retryAfterMs: cause.retryAfterMs ?? untilReset }
}

function nextLink(header: string | null, current: string): string | undefined {
  const value = header?.split(',').map((part) => /<([^>]+)>\s*;.*rel="?next"?/.exec(part)?.[1]).find(Boolean)
  if (!value) return undefined
  const next = new URL(value, current)
  if (next.origin !== 'https://api.github.com') throw new IngestConfigError('GitHub next page has an unexpected origin.')
  return next.toString()
}

import { definePipeline, defineStream, IngestConfigError, timestampWindow } from '@chkit/plugin-ingest'

import { classifyGitHubError, defaultGitHubClientDeps, type GitHubClientDeps } from './client.js'
import { githubConfig, type GitHubConfig } from './config.js'
import { github_issuesRaw, readIssues } from './sources/issues.js'
import { github_stargazersRaw, readStargazers } from './sources/stargazers.js'

export function createGitHubPipeline(config: GitHubConfig = githubConfig, deps: GitHubClientDeps = defaultGitHubClientDeps) {
  const source = { ...config, repositories: [...config.repositories], start: new Date(config.start) }
  if (!Number.isSafeInteger(config.pageSize) || config.pageSize < 1 || config.pageSize > 100) {
    throw new IngestConfigError('GitHub pageSize must be an integer between 1 and 100.')
  }
  if (config.repositories.some((repo) => !/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(repo))) {
    throw new IngestConfigError('GitHub repositories must use owner/repository names.')
  }
  return definePipeline({
    id: source.sourceId, tags: ['provider:github'], maxStreams: 1, maxFetches: 1,
    streams: source.repositories.flatMap((repo) => {
      const suffix = repo.replace('/', '.')
      const options = { classifyError: classifyGitHubError, tags: [`repository:${repo}`] }
      return [
        defineStream({
          ...options, id: `${source.sourceId}.issues.${suffix}`, tags: [...options.tags, 'resource:issues'], destination: github_issuesRaw,
          incremental: timestampWindow({ start: source.start, overlapMs: source.overlapMs }),
          read: (context) => readIssues(context, repo, source, deps),
        }),
        defineStream({
          ...options, id: `${source.sourceId}.stargazers.${suffix}`, tags: [...options.tags, 'resource:stargazers'], destination: github_stargazersRaw,
          read: (context) => readStargazers(context, repo, source, deps),
        }),
      ]
    }),
  })
}

export const githubPipeline = createGitHubPipeline()

import { IngestConfigError, rawRows, rawTable, type FetchContext, type ReadContext, type TimestampRange, type TimestampWindowState } from '@chkit/plugin-ingest'

import { readGitHubPages, requestGitHub, type GitHubClientDeps } from '../client.js'
import type { GitHubConfig } from '../config.js'

interface Issue { number: number; updated_at: string; pull_request?: { url: string }; [key: string]: unknown }

export const github_issuesRaw = rawTable({ database: 'default', name: 'github_issues_raw' })

export async function* readIssues(context: ReadContext<TimestampRange, TimestampWindowState>, repo: string, config: GitHubConfig, deps: GitHubClientDeps) {
  // GitHub's since filter is strict; overlap includes equal timestamps and recent changes.
  for await (const page of readGitHubPages<Issue>(context, { path: `/repos/${repo}/issues`, params: {
    state: 'all', sort: 'updated', direction: 'asc', since: context.selection.from.toISOString(),
  } }, config, deps)) {
    for (const issue of page) {
      if (!Number.isSafeInteger(issue.number) || !Number.isFinite(Date.parse(issue.updated_at))) {
        throw new IngestConfigError('GitHub issue has no valid number or updated_at.')
      }
      // REST has no until parameter. Enforce the cutoff locally; live pages are not snapshots.
      if (Date.parse(issue.updated_at) > context.selection.to.getTime()) continue
      const complete = await withIssueContext(context, repo, issue, config, deps)
      yield { rows: rawRows([complete], (item) => JSON.stringify([repo, item.number])) }
    }
  }
}

/** Load complete child conversations before publishing the parent observation. */
async function withIssueContext(context: FetchContext, repo: string, issue: Issue, config: GitHubConfig, deps: GitHubClientDeps) {
  const comment_items = await collect(context, `/repos/${repo}/issues/${issue.number}/comments`, config, deps)
  if (!issue.pull_request) return { ...issue, comment_items }
  const path = `/repos/${repo}/pulls/${issue.number}`
  const pull_detail = await context.attempt(async (signal) => {
    const response = await requestGitHub(`https://api.github.com${path}`, undefined, signal, deps)
    const detail: unknown = await response.json()
    if (!isObject(detail)) throw new IngestConfigError('GitHub pull request detail is not an object.')
    return detail
  }, { label: 'GET pull request detail' })
  const reviews = await collect(context, `${path}/reviews`, config, deps)
  const review_comments = await collect(context, `${path}/comments`, config, deps)
  const commits = await collect(context, `${path}/commits`, config, deps)
  const files = await collect(context, `${path}/files`, config, deps)
  return { ...issue, pull_detail, comment_items, reviews, review_comments, commits, files,
    _chkit_context: { files_complete: files.length === pull_detail.changed_files, commits_complete: commits.length === pull_detail.commits } }
}

async function collect(context: FetchContext, path: string, config: GitHubConfig, deps: GitHubClientDeps): Promise<Record<string, unknown>[]> {
  const items: Record<string, unknown>[] = []
  for await (const page of readGitHubPages<Record<string, unknown>>(context, { path }, config, deps)) items.push(...page)
  return items
}

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

import { IngestConfigError, rawRows, rawTable, type FetchContext } from '@chkit/plugin-ingest'

import { readGitHubPages, type GitHubClientDeps } from '../client.js'
import type { GitHubConfig } from '../config.js'

interface Stargazer { user: { id: number }; [key: string]: unknown }

export const github_stargazersRaw = rawTable({ database: 'default', name: 'github_stargazers_raw' })

export async function* readStargazers(context: FetchContext, repo: string, config: GitHubConfig, deps: GitHubClientDeps) {
  for await (const page of readGitHubPages<Stargazer>(context, { path: `/repos/${repo}/stargazers`, accept: 'application/vnd.github.star+json' }, config, deps)) {
    if (page.some((star) => !star.user || !Number.isSafeInteger(star.user.id))) throw new IngestConfigError('GitHub stargazer has no user ID.')
    yield { rows: rawRows(page, (star) => JSON.stringify([repo, star.user.id])) }
  }
}

import { afterEach, expect, test } from 'bun:test'
import { IngestConfigError, runIngestion, selectStreams } from '@chkit/plugin-ingest'
import { createMemoryDestination, createMemoryJournal } from '@chkit/plugin-ingest/testing'

import { createGitHubPipeline, githubPipeline } from '../index.js'
import { githubConfig } from '../config.js'

const originalFetch = globalThis.fetch
const originalToken = process.env.GITHUB_TOKEN
const cutoff = new Date('2026-01-02T00:00:00Z')

function setFetch(handler: (...args: Parameters<typeof fetch>) => Promise<Response>): void {
  globalThis.fetch = Object.assign(handler, { preconnect: originalFetch.preconnect })
  process.env.GITHUB_TOKEN = 'fixture'
}

function selected(resource = 'issues') {
  return selectStreams([githubPipeline], [`resource:${resource}`]).map((item) => ({ ...item, stream: { ...item.stream, batchSize: 1, retry: { retries: 0 } } }))
}

afterEach(() => {
  globalThis.fetch = originalFetch
  if (originalToken === undefined) delete process.env.GITHUB_TOKEN
  else process.env.GITHUB_TOKEN = originalToken
})

test.serial('GitHub follows short-page Link continuations, bounds updates and preserves complete PR context', async () => {
  const paths: string[] = []
  setFetch(async (input) => {
    const url = new URL(String(input))
    paths.push(url.pathname + url.search)
    if (url.pathname.endsWith('/issues')) {
      expect(url.searchParams.get('since')).toBe('2008-01-01T00:00:00.000Z')
      expect(url.searchParams.get('sort')).toBe('updated')
      expect(url.searchParams.get('direction')).toBe('asc')
      if (url.searchParams.has('page')) return Response.json([
        { number: 2, updated_at: '2026-01-01T12:00:00Z', pull_request: { url: 'detail' } },
        { number: 3, updated_at: '2026-01-03T00:00:00Z' },
      ])
      return Response.json([{ number: 1, updated_at: '2026-01-01T12:00:00Z' }], {
        headers: { Link: `<https://api.github.com/repos/obsessiondb/chkit/issues?per_page=100&page=2&since=2008-01-01T00%3A00%3A00.000Z&sort=updated&direction=asc>; rel="next"` },
      })
    }
    if (url.pathname.endsWith('/pulls/2')) return Response.json({ changed_files: 2, commits: 1, custom: 'preserved' })
    if (url.pathname.endsWith('/files')) return Response.json([{ filename: 'file.ts' }])
    if (url.pathname.endsWith('/commits')) return Response.json([{ sha: 'a' }])
    return Response.json([{ id: 11, body: 'context' }])
  })
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  const result = await runIngestion({ selected: selected(), backfill: undefined }, { journal, destination, now: () => cutoff })
  expect(result.ok).toBe(true)
  const rows = destination.tables.get('default.github_issues_raw') ?? []
  expect(rows.map((row) => row.id)).toEqual(['["obsessiondb/chkit",1]', '["obsessiondb/chkit",2]'])
  expect(rows[1]?.raw).toMatchObject({ pull_detail: { custom: 'preserved' }, comment_items: [{ id: 11 }], _chkit_context: { files_complete: false, commits_complete: true } })
  expect(paths.some((path) => path.includes('/issues/3/comments'))).toBe(false)
  expect((await journal.readCheckpoint('github.issues.obsessiondb.chkit')).envelope?.state).toEqual({ watermark: cutoff.toISOString() })
})

test.serial('GitHub child failures replay the issue window and destination failures cannot advance it', async () => {
  let failComments = true
  const starts: string[] = []
  setFetch(async (input) => {
    const url = new URL(String(input))
    if (url.pathname.endsWith('/issues')) {
      starts.push(url.searchParams.get('since') ?? '')
      return Response.json([{ number: 1, updated_at: '2026-01-01T12:00:00Z' }])
    }
    return failComments ? new Response('denied', { status: 403 }) : Response.json([])
  })
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  const request = { selected: selected(), backfill: undefined }
  expect((await runIngestion(request, { journal, destination, now: () => cutoff })).ok).toBe(false)
  expect((await journal.readCheckpoint('github.issues.obsessiondb.chkit')).envelope).toBeUndefined()
  failComments = false
  expect((await runIngestion(request, { journal, destination: { insert: async () => { throw new IngestConfigError('sink rejected') } }, now: () => cutoff })).ok).toBe(false)
  expect((await journal.readCheckpoint('github.issues.obsessiondb.chkit')).envelope).toBeUndefined()
  expect((await runIngestion(request, { journal, destination, now: () => cutoff })).ok).toBe(true)
  expect(starts).toEqual(Array(3).fill('2008-01-01T00:00:00.000Z'))
})

test.serial('GitHub subsequent issue scans overlap the committed watermark', async () => {
  const starts: string[] = []
  setFetch(async (input) => {
    starts.push(new URL(String(input)).searchParams.get('since') ?? '')
    return Response.json([])
  })
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  const request = { selected: selected(), backfill: undefined }
  expect((await runIngestion(request, { journal, destination, now: () => cutoff })).ok).toBe(true)
  expect((await runIngestion(request, { journal, destination, now: () => new Date('2026-01-03T00:00:00Z') })).ok).toBe(true)
  expect(starts).toEqual(['2008-01-01T00:00:00.000Z', '2026-01-01T23:55:00.000Z'])
})

test.serial('GitHub empty stargazer full syncs journal completion and always read again', async () => {
  const paths: string[] = []
  setFetch(async (input) => { paths.push(String(input)); return Response.json([]) })
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  const request = { selected: selected('stargazers'), backfill: undefined }
  expect((await runIngestion(request, { journal, destination, now: () => cutoff })).ok).toBe(true)
  expect((await runIngestion(request, { journal, destination, now: () => new Date('2026-01-03T00:00:00Z') })).ok).toBe(true)
  expect(paths).toHaveLength(2)
  expect(paths.every((path) => !new URL(path).searchParams.has('since'))).toBe(true)
  const state = await journal.readCheckpoint('github.stargazers.obsessiondb.chkit')
  expect(state.envelope).toBeUndefined()
  expect(state.lastSuccessSeq).toBeGreaterThan(0)
  expect(journal.events.filter((event) => event.namespaceId === 'github.stargazers.obsessiondb.chkit' && event.eventKind === 'work_finished' && event.workState === 'succeeded')).toHaveLength(2)
})

test.serial('GitHub binds configuration and isolates resource and repository failures in one pipeline', async () => {
  const requests: URL[] = []
  let failFirstIssues = true
  const config = {
    ...githubConfig, sourceId: 'github.fixture', repositories: ['first/repo', 'second/repo'],
    pageSize: 25, start: new Date('2025-01-01'), overlapMs: 60_000,
  }
  const pipeline = createGitHubPipeline(config, {
    token: () => 'bound-token',
    fetch: async (input, init) => {
      const url = new URL(input)
      requests.push(url)
      expect(new Headers(init.headers).get('authorization')).toBe('Bearer bound-token')
      expect(url.searchParams.get('per_page')).toBe('25')
      if (url.pathname === '/repos/first/repo/issues' && failFirstIssues) return new Response('denied', { status: 403 })
      if (url.pathname.endsWith('/stargazers')) return Response.json([{ user: { id: 9 }, custom: true }])
      return Response.json([])
    },
  })
  config.pageSize = 100
  config.repositories.push('third/repo')
  config.start.setUTCFullYear(2000)
  config.overlapMs = 60 * 60 * 1000
  expect(pipeline.streams.map((stream) => stream.id)).toEqual([
    'github.fixture.issues.first.repo', 'github.fixture.stargazers.first.repo',
    'github.fixture.issues.second.repo', 'github.fixture.stargazers.second.repo',
  ])
  const selected = selectStreams([pipeline], []).map((item) => ({ ...item, stream: { ...item.stream, retry: { retries: 0 } } }))
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  const result = await runIngestion({ selected, backfill: undefined }, { journal, destination, now: () => cutoff })
  expect(result.ok).toBe(false)
  expect(result.streams.filter((stream) => stream.outcome === 'succeeded')).toHaveLength(3)
  expect((await journal.readCheckpoint('github.fixture.issues.first.repo')).envelope).toBeUndefined()
  expect((await journal.readCheckpoint('github.fixture.issues.second.repo')).envelope?.state).toEqual({ watermark: cutoff.toISOString() })
  expect(destination.tables.get('default.github_stargazers_raw')?.map((row) => row.id)).toEqual(['["first/repo",9]', '["second/repo",9]'])
  expect(requests.filter((url) => url.pathname.endsWith('/issues')).every((url) => url.searchParams.get('since') === '2025-01-01T00:00:00.000Z')).toBe(true)

  requests.length = 0
  failFirstIssues = false
  const onlySecondIssues = selectStreams([pipeline], ['repository:second/repo', 'resource:issues'])
  expect(onlySecondIssues.map((item) => item.stream.id)).toEqual(['github.fixture.issues.second.repo'])
  expect((await runIngestion({ selected: onlySecondIssues, backfill: undefined }, { journal, destination, now: () => new Date('2026-01-03') })).ok).toBe(true)
  expect(requests.map((url) => url.pathname)).toEqual(['/repos/second/repo/issues'])
  expect(requests[0]?.searchParams.get('since')).toBe('2026-01-01T23:59:00.000Z')
  expect((await journal.readCheckpoint('github.fixture.issues.first.repo')).envelope).toBeUndefined()
})

test.serial('GitHub retries each paginated request once under executor authority', async () => {
  let attempts = 0
  const pipeline = createGitHubPipeline(githubConfig, {
    token: () => 'fixture',
    fetch: async () => {
      attempts++
      if (attempts === 1) return new Response('rate limited', { status: 403, headers: { 'x-ratelimit-remaining': '0', 'retry-after': '0' } })
      return Response.json([])
    },
  })
  const selected = selectStreams([pipeline], ['resource:stargazers']).map((item) => ({ ...item, stream: { ...item.stream, retry: { retries: 1, minTimeout: 0, maxTimeout: 0 } } }))
  const journal = createMemoryJournal()
  const result = await runIngestion({ selected, backfill: undefined }, { journal, destination: createMemoryDestination(), now: () => cutoff })
  expect(result.ok).toBe(true)
  expect(attempts).toBe(2)
  expect(journal.events.filter((event) => event.eventKind === 'retry_scheduled' && event.errorClass === 'rate_limited')).toHaveLength(1)
})

test.serial('GitHub stargazer failures replay from the first page before journaling full-sync completion', async () => {
  let failSecondPage = true
  const starts: string[] = []
  setFetch(async (input) => {
    const url = new URL(String(input))
    if (url.searchParams.has('page')) return failSecondPage ? new Response('denied', { status: 403 }) : Response.json([{ user: { id: 43 } }])
    starts.push(url.search)
    return Response.json([{ user: { id: 42 } }], { headers: { Link: '<https://api.github.com/repos/obsessiondb/chkit/stargazers?per_page=100&page=2>; rel="next"' } })
  })
  const journal = createMemoryJournal()
  const destination = createMemoryDestination()
  const request = { selected: selected('stargazers'), backfill: undefined }
  expect((await runIngestion(request, { journal, destination, now: () => cutoff })).ok).toBe(false)
  expect((await journal.readCheckpoint('github.stargazers.obsessiondb.chkit')).lastSuccessSeq).toBe(0)
  failSecondPage = false
  expect((await runIngestion(request, { journal, destination: { insert: async () => { throw new IngestConfigError('sink rejected') } }, now: () => cutoff })).ok).toBe(false)
  expect((await journal.readCheckpoint('github.stargazers.obsessiondb.chkit')).lastSuccessSeq).toBe(0)
  expect((await runIngestion(request, { journal, destination, now: () => cutoff })).ok).toBe(true)
  const completed = await journal.readCheckpoint('github.stargazers.obsessiondb.chkit')
  expect(completed.envelope).toBeUndefined()
  expect(completed.lastSuccessSeq).toBeGreaterThan(0)
  expect(starts).toEqual(Array(3).fill('?per_page=100'))
  expect(destination.tables.get('default.github_stargazers_raw')?.map((row) => row.id)).toEqual(['["obsessiondb/chkit",42]', '["obsessiondb/chkit",43]'])
})

test.serial('GitHub refuses repeated and foreign-origin Link continuations without completing the stream', async () => {
  for (const next of ['https://api.github.com/repos/obsessiondb/chkit/stargazers?per_page=100', 'https://example.com/steal']) {
    let requests = 0
    setFetch(async () => {
      requests++
      return Response.json([], { headers: { Link: `<${next}>; rel="next"` } })
    })
    const journal = createMemoryJournal()
    const result = await runIngestion({ selected: selected('stargazers'), backfill: undefined }, { journal, destination: createMemoryDestination(), now: () => cutoff })
    expect(result.ok).toBe(false)
    expect(requests).toBe(1)
    expect((await journal.readCheckpoint('github.stargazers.obsessiondb.chkit')).lastSuccessSeq).toBe(0)
  }
})
